def move_zeros(arr):
    non_zero = []
    zeros = []
    for x in arr:
        if x == 0:
            zeros.append(x)
        else:
            non_zero.append(x)
    return non_zero + zeros

reference_solution:
def move_zeros(arr):
    write = 0
    for i in range(len(arr)):
        if arr[i] != 0:
            arr[write], arr[i] = arr[i], arr[write]
            write += 1
    return arr
